from __future__ import annotations

import hashlib
import json
import os
import re
import shutil
import sys
from pathlib import Path

import pytest

from sbc_imager.assembler import assemble
from sbc_imager.runner import SubprocessRunner

pytestmark = [
    pytest.mark.integration,
    pytest.mark.skipif(sys.platform != "linux", reason="loop/mount/exfat require Linux"),
]

MIB = 1024 * 1024
PARTITION_BYTES = 63 * MIB
IMAGE_BYTES = 64 * MIB
SETTINGS = {"path": "Cannoli/Config/settings.json", "content": "{}\n"}
CREDITS = {
    "path": "CREDITS.md",
    "content": "# Credits\n\nGenerated by sbc-imager.\n",
}


def _write(path: Path, data: bytes) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)
    return path


def _entry(stage_dir: Path, dest: str, data: bytes) -> dict[str, object]:
    path = _write(stage_dir / dest, data)
    return {
        "dest": dest,
        "src": str(path),
        "kind": "rom",
        "size": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
    }


def _content_bytes(entries: list[dict[str, object]]) -> int:
    total = 0
    for entry in entries:
        size = entry["size"]
        assert isinstance(size, int)
        total += size
    return total


def _plan(stage_dir: Path, entries: list[dict[str, object]]) -> dict[str, object]:
    return {
        "schema_version": 1,
        "cannoli_version": "1.9.1",
        "image_bytes": IMAGE_BYTES,
        "partition_bytes": PARTITION_BYTES,
        "partition_offset_bytes": MIB,
        "label": "CANNOLI",
        "required_dirs": ["Cannoli", "Cannoli/Roms/GBA", "Cannoli/Roms/SNES", "APKs"],
        "settings_marker": SETTINGS,
        "credits_marker": CREDITS,
        "entries": entries,
        "totals": {
            "entries": len(entries),
            "content_bytes": _content_bytes(entries),
        },
    }


def test_assemble_when_loop_and_exfat_are_available_builds_verified_image(
    tmp_path: Path,
) -> None:
    if os.geteuid() != 0:
        pytest.skip("requires root to attach loops and mount exFAT")
    stage_dir = tmp_path / "stage"
    stage_dir.mkdir()
    entries = [
        _entry(stage_dir, "Cannoli/Roms/GBA/demo.gba", b"DEMO ROM\n"),
        _entry(stage_dir, "APKs/Demo.apk", b"APK\n"),
    ]
    plan_path = tmp_path / "stage-plan.json"
    plan_path.write_text(json.dumps(_plan(stage_dir, entries)), encoding="utf-8")
    out = tmp_path / "card.img"
    work = tmp_path / "work"
    runner = SubprocessRunner()

    report = assemble(stage_dir, plan_path, out, work, runner)

    assert out.is_file()
    assert out.stat().st_size == IMAGE_BYTES
    assert not Path(str(out) + ".partial").exists()
    assert report.fsck_ok is True
    assert report.label == "CANNOLI"
    assert report.content_files == 2
    assert report.content_bytes == 13

    tree = json.loads((work / "tree.json").read_text(encoding="utf-8"))
    digests = {item["dest"]: item["sha256"] for item in tree}
    assert digests == {
        "Cannoli/Roms/GBA/demo.gba": hashlib.sha256(b"DEMO ROM\n").hexdigest(),
        "APKs/Demo.apk": hashlib.sha256(b"APK\n").hexdigest(),
        SETTINGS["path"]: hashlib.sha256(SETTINGS["content"].encode()).hexdigest(),
        CREDITS["path"]: hashlib.sha256(CREDITS["content"].encode()).hexdigest(),
    }
    report_payload = json.loads((work / "report.json").read_text(encoding="utf-8"))
    assert report_payload["fsck_ok"] is True
    assert (
        report_payload["tree_sha256"]
        == hashlib.sha256((work / "tree.json").read_bytes()).hexdigest()
    )

    sfdisk = shutil.which("sfdisk")
    if sfdisk is not None:
        partition = runner.run([sfdisk, "-d", str(out)]).stdout
        assert re.search(r"start=\s*2048\b", partition), partition
        assert re.search(r"Id=\s*7\b", partition), partition
    else:
        header = out.read_bytes()[:512]
        assert header[450] == 0x07
        assert int.from_bytes(header[454:458], "little") == 2048
        assert header[510:512] == b"\x55\xaa"

    loop = runner.run(
        [
            "losetup",
            "--find",
            "--show",
            "--offset",
            str(MIB),
            "--sizelimit",
            str(PARTITION_BYTES),
            str(out),
        ]
    ).stdout.strip()
    mountpoint = tmp_path / "verify-mnt"
    mountpoint.mkdir()
    try:
        fsck = runner.run(["fsck.exfat", "-n", loop], check=False)
        assert fsck.returncode == 0, fsck.stderr
        runner.run(["mount", "-t", "exfat", "-o", "ro", loop, str(mountpoint)])
        try:
            assert (mountpoint / "Cannoli/Roms/GBA/demo.gba").read_bytes() == b"DEMO ROM\n"
            assert (mountpoint / "APKs/Demo.apk").read_bytes() == b"APK\n"
            assert (mountpoint / SETTINGS["path"]).read_text(encoding="utf-8") == (
                SETTINGS["content"]
            )
            assert (mountpoint / CREDITS["path"]).read_text(encoding="utf-8") == (
                CREDITS["content"]
            )
            assert (mountpoint / "Cannoli/Roms/SNES").is_dir()
        finally:
            runner.run(["umount", str(mountpoint)], check=False)
    finally:
        runner.run(["losetup", "-d", loop], check=False)

    attached = runner.run(["losetup", "-a"], check=False).stdout
    assert str(out) not in attached
